class Edge {
public:
    int source;
    int target;

    Edge(int source, int target) : source(source), target(target){};

    

};

class Board {
public:
    bool directed;
    std::map<int, Node> nodes;
    std::vector<Edge> edges;

    explicit Board(bool directed) : directed(directed) {}

    void addNode(int id, int x, int y) {
        nodes.insert(std::make_pair(id, Node(id, x, y)));
    }

    void addEdge(int source, int target) {
        edges.emplace_back(source, target);
        nodes.at(source).neighbors.push_back(target);
        if (!directed && source != target) {
            nodes.at(target).neighbors.push_back(source);
        }
    }

    // Returns every node at most `v` edges away from `n` (including `n` at distance 0).
    std::vector<Node*> nodesWithinDistance(const Node& n, int v) {
        return nodesWithinDistance(n.id, v);
    }

    std::vector<Node*> nodesWithinDistance(int n, int v) {
        std::vector<Node*> result;
        if (v < 0 || nodes.find(n) == nodes.end()) {
            return result;
        }

        std::queue<std::pair<int, int>> frontier;
        std::unordered_set<int> visited;

        frontier.push({n, 0});
        visited.insert(n);

        while (!frontier.empty()) {
            int id = frontier.front().first;
            int dist = frontier.front().second;
            frontier.pop();

            result.push_back(&nodes.at(id));
            if (dist == v) {
                continue;
            }

            for (int neighborId : nodes.at(id).neighbors) {
                if (visited.insert(neighborId).second) {
                    frontier.push({neighborId, dist + 1});
                }
            }
        }

        return result;
    }
};

